package com.android.tools.lint.checks;

imports...

public class AndroidAutoDetector extends Detector implements XmlScanner, SourceCodeScanner {

    private static final String ACTION_PLAY_FROM_SEARCH = "android.media.action.PLAY_FROM_SEARCH";
    private static final String METHOD_ON_PLAY_FROM_SEARCH = "onPlayFromSearch";
    private static final String MEDIA_SESSION_CALLBACK = "android.media.session.MediaSession$Callback";
    private static final String MEDIA_SESSION_COMPAT_CALLBACK = "android.support.v4.media.session.MediaSessionCompat$Callback";
    private static final String MEDIA_SESSION_COMPAT_CALLBACK_ANDROIDX = "androidx.media.session.MediaSessionCompat$Callback";

    public static final Issue ISSUE = Issue.create(
            "MissingOnPlayFromSearch",
            "Missing onPlayFromSearch implementation",
            "To support voice searches on Android Auto, in addition to adding an intent-filter "
                    + "for the action `" + ACTION_PLAY_FROM_SEARCH + "`, you also need to override "
                    + "and implement `" + METHOD_ON_PLAY_FROM_SEARCH + "(String query, Bundle bundle)`.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(
                    AndroidAutoDetector.class,
                    EnumSet.of(Scope.MANIFEST, Scope.JAVA_FILE)
            )
    );

    private boolean mHasAction;
    private boolean mHasMethod;
    private Location mActionLocation;

    @Override
    public void beforeCheckEachProject(@NotNull Context context) {
        mHasAction = false;
        mHasMethod = false;
        mActionLocation = null;
    }

    @Override
    public void afterCheckEachProject(@NotNull Context context) {
        if (mHasAction && !mHasMethod && mActionLocation != null) {
            context.report(ISSUE, mActionLocation,
                    "The manifest declares the `" + ACTION_PLAY_FROM_SEARCH + "` action, but no `"
                            + METHOD_ON_PLAY_FROM_SEARCH + "(String, Bundle)` override was found.");
        }
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList("action");
    }

    @Override
    public void visitElement(@NotNull XmlContext context, @NotNull Element element) {
        String name = element.getAttributeNS(SdkConstants.ANDROID_URI, "name");
        if (ACTION_PLAY_FROM_SEARCH.equals(name)) {
            mHasAction = true;
            mActionLocation = context.getLocation(element);
        }
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UMethod.class);
    }

    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitMethod(@NotNull UMethod node) {
                if (!METHOD_ON_PLAY_FROM_SEARCH.equals(node.getName())) {
                    return;
                }
                List<UParameter> params = node.getUastParameters();
                if (params.size() != 2) {
                    return;
                }
                if (!"java.lang.String".equals(params.get(0).getType().getCanonicalText())
                        || !"android.os.Bundle".equals(params.get(1).getType().getCanonicalText())) {
                    return;
                }
                PsiClass containingClass = node.getContainingClass();
                if (containingClass == null) {
                    return;
                }
                JavaEvaluator evaluator = context.getEvaluator();
                if (evaluator.extendsClass(containingClass, MEDIA_SESSION_CALLBACK, false)
                        || evaluator.extendsClass(containingClass, MEDIA_SESSION_COMPAT_CALLBACK, false)
                        || evaluator.extendsClass(containingClass, MEDIA_SESSION_COMPAT_CALLBACK_ANDROIDX, false)) {
                    mHasMethod = true;
                }
            }
        };
    }
}

