```java
public class AndroidAutoDetector extends Detector implements XmlScanner, SourceCodeScanner {
    private static final String ACTION_PLAY_FROM_SEARCH = "android.media.action.PLAY_FROM_SEARCH";
    private static final String ON_PLAY_FROM_SEARCH = "onPlayFromSearch";
    private static final String MEDIA_SESSION_CALLBACK = "android.media.session.MediaSession.Callback";
    private static final String MEDIA_SESSION_COMPAT_CALLBACK = "android.support.v4.media.session.MediaSessionCompat.Callback";
    private static final String ANDROIDX_MEDIA_SESSION_COMPAT_CALLBACK = "androidx.media.session.MediaSessionCompat.Callback";

    /** Missing onPlayFromSearch */
    public static final Issue ISSUE = Issue.create(
            "MissingOnPlayFromSearch",
            "Missing `onPlayFromSearch`",
            "To support voice searches on Android Auto, ...",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(AndroidAutoDetector.class, EnumSet.of(Scope.MANIFEST, Scope.JAVA_FILE)));

    private boolean mHasPlayFromSearch;
    private boolean mHasOnPlayFromSearch;
    private Location mActionLocation;

    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        mHasPlayFromSearch = false;
        mHasOnPlayFromSearch = false;
        mActionLocation = null;
    }

    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        if (mHasPlayFromSearch && !mHasOnPlayFromSearch && mActionLocation != null) {
            context.report(ISSUE, mActionLocation,
                "The manifest declares the `android.media.action.PLAY_FROM_SEARCH` action, but no `onPlayFromSearch(String, Bundle)` override was found.");
        }
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(SdkConstants.TAG_ACTION);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (ACTION_PLAY_FROM_SEARCH.equals(element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME))) {
            mHasPlayFromSearch = true;
            mActionLocation = context.getLocation(element);
        }
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UMethod.class);
    }

    @Override
    public UElementHandler createUastHandler(@NonNull final JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitMethod(@NonNull UMethod node) {
                if (!ON_PLAY_FROM_SEARCH.equals(node.getName())) return;
                if (node.getUastParameters().size() != 2) return;
                UParameter param1 = node.getUastParameters().get(0);
                UParameter param2 = node.getUastParameters().get(1);
                if (!"java.lang.String".equals(param1.getType().getCanonicalText()) ||
                    !"android.os.Bundle".equals(param2.getType().getCanonicalText())) return;
                PsiClass cls = node.getContainingClass();
                if (cls == null) return;
                JavaEvaluator eval = context.getEvaluator();
                if (eval.extendsClass(cls, MEDIA_SESSION_CALLBACK, false) ||
                    eval.extendsClass(cls, MEDIA_SESSION_COMPAT_CALLBACK, false) ||
                    eval.extendsClass(cls, ANDROIDX_MEDIA_SESSION_COMPAT_CALLBACK, false)) {
                    mHasOnPlayFromSearch = true;
                }
            }
        };
    }
}
```

